import React, { useState, useEffect } from 'react';
import API from '../api/axios';
import {
  Utensils,
  Key,
  Power,
  Search,
  Plus,
  Layers,
  X,
  Trash2
} from 'lucide-react';

export default function Restaurants() {
  const [searchQuery, setSearchQuery] = useState('');
  const [restaurants, setRestaurants] = useState([]);
  const [loading, setLoading] = useState(true);

  // Modal States
  const [selectedRest, setSelectedRest] = useState(null);
  const [newProduct, setNewProduct] = useState({ name: '', price: '', priority: 1 });
  const [isAddRestOpen, setIsAddRestOpen] = useState(false);
  const [newRest, setNewRest] = useState({
    name: '',
    phone: '',
    password: '',
    orderType: 'both',
    priority: 1
  });

  useEffect(() => {
    fetchRestaurants();
  }, []);

  const fetchRestaurants = async () => {
    try {
      setLoading(true);
      const res = await API.get('/restaurants');
      setRestaurants(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      console.error('Failed to load restaurants from DB:', err.message);
    } finally {
      setLoading(false);
    }
  };

  const toggleStatus = async (id) => {
    try {
      const res = await API.patch(`/restaurants/${id}/toggle`);
      setRestaurants(restaurants.map(r => r.id === id ? { ...r, is_open: res.data.is_open } : r));
    } catch (err) {
      alert('DB Error: স্ট্যাটাস আপডেট করা যায়নি!');
    }
  };

  const handlePriorityChange = async (id, newPriority) => {
    const pValue = Number(newPriority) || 1;
    setRestaurants(restaurants.map(r => r.id === id ? { ...r, priority: pValue } : r));
    try {
      await API.patch(`/restaurants/${id}/priority`, { priority: pValue });
    } catch (err) {
      console.error('Priority update error:', err.message);
    }
  };

  const handleAddRestaurant = async (e) => {
    e.preventDefault();
    if (!newRest.name || !newRest.phone || !newRest.password) return;
    try {
      const res = await API.post('/restaurants', {
        name: newRest.name,
        phone: newRest.phone,
        password: newRest.password,
        orderType: newRest.orderType,
        order_type: newRest.orderType,
        priority: Number(newRest.priority) || 1
      });
      if (res.data) {
        setRestaurants([res.data, ...restaurants]);
        setIsAddRestOpen(false);
        setNewRest({ name: '', phone: '', password: '', orderType: 'both', priority: 1 });
        alert('রেস্টুরেন্ট সফলভাবে সেভ হয়েছে!');
      }
    } catch (err) {
      const errorMsg = err.response?.data?.error || err.message;
      alert(`DB Error: রেস্টুরেন্ট সেভ হয়নি! (${errorMsg})`);
    }
  };

  const handleAddProduct = async (e) => {
    e.preventDefault();
    if (!newProduct.name || !newProduct.price) return;
    try {
      const payload = {
        restaurant_id: selectedRest.id,
        name: newProduct.name,
        price: Number(newProduct.price),
        priority: Number(newProduct.priority) || 1
      };
      const res = await API.post('/products', payload);
      const updatedRest = {
        ...selectedRest,
        products: [...(selectedRest.products || []), res.data]
      };
      setRestaurants(restaurants.map(r => r.id === selectedRest.id ? updatedRest : r));
      setSelectedRest(updatedRest);
      setNewProduct({ name: '', price: '', priority: 1 });
    } catch (err) {
      alert('DB Error: প্রোডাক্ট সেভ হয়নি!');
    }
  };

  const toggleProductStock = async (prodId) => {
    try {
      const res = await API.patch(`/products/${prodId}/toggle-stock`);
      const updatedProducts = selectedRest.products.map(p =>
        p.id === prodId ? { ...p, in_stock: res.data.in_stock } : p
      );
      const updatedRest = { ...selectedRest, products: updatedProducts };
      setSelectedRest(updatedRest);
      setRestaurants(restaurants.map(r => r.id === selectedRest.id ? updatedRest : r));
    } catch (err) {
      alert('DB Error: স্টক স্ট্যাটাস আপডেট হয়নি!');
    }
  };

  const handleDeleteProduct = async (prodId) => {
    if (!window.confirm('আপনি কি নিশ্চিত এই প্রোডাক্টটি ডিলিট করতে চান?')) return;
    try {
      await API.delete(`/products/${prodId}`);
      const updatedProducts = selectedRest.products.filter(p => p.id !== prodId);
      const updatedRest = { ...selectedRest, products: updatedProducts };
      setSelectedRest(updatedRest);
      setRestaurants(restaurants.map(r => r.id === selectedRest.id ? updatedRest : r));
    } catch (err) {
      alert('DB Error: প্রোডাক্ট ডিলিট হয়নি!');
    }
  };

  const filteredRestaurants = restaurants.filter(r =>
    (r.name && r.name.toLowerCase().includes(searchQuery.toLowerCase())) ||
    (r.phone && r.phone.includes(searchQuery))
  );

  return (
    <div className="p-8 space-y-6 bg-gray-50 min-h-screen">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-900 tracking-tight">Restaurant Management</h1>
          <p className="text-sm text-gray-500">লাইভ ডাটাবেজ পরিচালিত রেস্টুরেন্ট, মেনু ও প্রায়োরিটি কন্ট্রোল</p>
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <Search className="w-4 h-4 absolute left-3 top-3 text-gray-400" />
            <input
              type="text"
              placeholder="Search restaurant or phone..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-9 pr-4 py-2 border border-gray-200 rounded-xl bg-white text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
            />
          </div>
          <button
            onClick={() => setIsAddRestOpen(true)}
            className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-xl font-bold hover:bg-emerald-700 shadow-md shadow-emerald-600/20 text-sm"
          >
            <Plus className="w-4 h-4" /> Add Restaurant
          </button>
        </div>
      </div>

      {loading ? (
        <div className="p-12 text-center text-gray-500 font-bold">ডাটাবেজ থেকে রেস্টুরেন্ট লোড হচ্ছে...</div>
      ) : (
        <div className="grid grid-cols-1 gap-4">
          {filteredRestaurants.map((res) => (
            <div key={res.id} className="bg-white p-5 rounded-2xl border border-emerald-100/70 shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-4 hover:shadow-md transition-shadow">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-emerald-50 text-emerald-700 flex items-center justify-center font-bold">
                  <Utensils className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="font-bold text-gray-900 text-base">{res.name}</h3>
                  <p className="text-xs text-gray-500">Phone: {res.phone}</p>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-[11px] font-bold text-emerald-800 bg-emerald-50 px-2 py-0.5 rounded uppercase">
                      Mode: {res.order_type || res.orderType}
                    </span>
                    <span className="text-xs text-gray-400">
                      Menu Items: <strong className="text-gray-700">{res.products?.length || 0}</strong>
                    </span>
                  </div>
                </div>
              </div>

              <div className="flex flex-wrap items-center gap-4 w-full md:w-auto justify-between md:justify-end">
                <div className="flex items-center gap-1.5 bg-gray-50 px-2.5 py-1 rounded-lg border border-gray-200">
                  <span className="text-xs text-gray-500 font-bold">Priority:</span>
                  <input
                    type="number"
                    value={res.priority}
                    onChange={(e) => handlePriorityChange(res.id, e.target.value)}
                    className="w-12 bg-white text-center font-bold text-sm border rounded py-0.5 focus:outline-none focus:ring-1 focus:ring-emerald-500"
                  />
                </div>

                <div className="text-right">
                  <span className="text-[10px] text-gray-400 font-bold uppercase block">TOTAL SELL</span>
                  <span className="text-base font-black text-emerald-600">৳ {res.total_sales || 0}</span>
                </div>

                <button
                  onClick={() => setSelectedRest(res)}
                  className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-lg text-xs font-bold hover:bg-emerald-100"
                >
                  <Layers className="w-3.5 h-3.5" /> Manage Menu
                </button>

                <button
                  onClick={() => toggleStatus(res.id)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                    res.is_open ? 'bg-emerald-100 text-emerald-800' : 'bg-red-100 text-red-700'
                  }`}
                >
                  <Power className="w-3.5 h-3.5" />
                  {res.is_open ? 'OPEN' : 'CLOSED'}
                </button>

                <button
                  onClick={async () => {
                    const pass = prompt(`Set new password for ${res.name}:`);
                    if (pass) {
                      try {
                        await API.patch(`/restaurants/${res.id}/password`, { password: pass });
                        alert('Password updated in DB!');
                      } catch {
                        alert('Password update failed!');
                      }
                    }
                  }}
                  className="p-2 border border-gray-200 rounded-lg hover:bg-gray-50 text-gray-600"
                  title="Change Password"
                >
                  <Key className="w-4 h-4" />
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Manage Menu Modal */}
      {selectedRest && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-white w-full max-w-2xl rounded-2xl p-6 space-y-5 shadow-2xl">
            <div className="flex justify-between items-center border-b pb-3">
              <div>
                <h3 className="font-bold text-gray-900 text-base">{selectedRest.name} - Menu Management</h3>
                <p className="text-xs text-gray-500">প্রোডাক্ট লিস্ট, দাম এবং প্রায়োরিটি সাজান</p>
              </div>
              <button onClick={() => setSelectedRest(null)} className="p-1 text-gray-400 hover:text-black">
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleAddProduct} className="grid grid-cols-1 sm:grid-cols-4 gap-2.5 bg-gray-50 p-3.5 rounded-xl border border-gray-200">
              <input
                type="text"
                placeholder="Product Name"
                value={newProduct.name}
                onChange={(e) => setNewProduct({ ...newProduct, name: e.target.value })}
                className="sm:col-span-2 px-3 py-1.5 border border-gray-200 rounded-lg text-xs focus:ring-1 focus:ring-emerald-500 bg-white"
              />
              <input
                type="number"
                placeholder="Price (৳)"
                value={newProduct.price}
                onChange={(e) => setNewProduct({ ...newProduct, price: e.target.value })}
                className="px-3 py-1.5 border border-gray-200 rounded-lg text-xs focus:ring-1 focus:ring-emerald-500 bg-white"
              />
              <button type="submit" className="bg-emerald-600 text-white rounded-lg text-xs font-bold hover:bg-emerald-700 py-2">
                + Add Item
              </button>
            </form>

            <div className="max-h-72 overflow-y-auto space-y-2.5 pr-1">
              {selectedRest.products?.map((item) => (
                <div key={item.id} className="flex justify-between items-center p-3 border border-gray-100 rounded-xl bg-white text-xs shadow-sm">
                  <div>
                    <span className="font-bold text-gray-800 text-sm">{item.name}</span>
                    <span className="text-gray-400 ml-2">Priority: #{item.priority}</span>
                  </div>
                  <div className="flex items-center gap-3">
                    <span className="font-black text-emerald-700">৳ {item.price}</span>
                    <button
                      onClick={() => toggleProductStock(item.id)}
                      className={`px-2.5 py-1 rounded text-xs font-bold ${
                        item.in_stock ? 'bg-emerald-100 text-emerald-800' : 'bg-red-100 text-red-700'
                      }`}
                    >
                      {item.in_stock ? 'In Stock' : 'Out of Stock'}
                    </button>
                    <button
                      onClick={() => handleDeleteProduct(item.id)}
                      className="text-gray-400 hover:text-red-600 p-1"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Add Restaurant Modal */}
      {isAddRestOpen && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-white w-full max-w-md rounded-2xl p-6 space-y-4 shadow-2xl">
            <div className="flex justify-between items-center border-b pb-3">
              <h3 className="font-bold text-gray-900 text-base">Add New Restaurant</h3>
              <button onClick={() => setIsAddRestOpen(false)} className="p-1 text-gray-400 hover:text-black">
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleAddRestaurant} className="space-y-3 text-xs font-medium">
              <div>
                <label className="block mb-1 text-gray-600 font-bold">Restaurant Name</label>
                <input
                  type="text"
                  required
                  value={newRest.name}
                  onChange={(e) => setNewRest({ ...newRest, name: e.target.value })}
                  placeholder="e.g. Sultan's Dine"
                  className="w-full px-3 py-2 border rounded-xl"
                />
              </div>

              <div>
                <label className="block mb-1 text-gray-600 font-bold">Phone Number</label>
                <input
                  type="text"
                  required
                  value={newRest.phone}
                  onChange={(e) => setNewRest({ ...newRest, phone: e.target.value })}
                  placeholder="017xxxxxxxx"
                  className="w-full px-3 py-2 border rounded-xl"
                />
              </div>

              <div>
                <label className="block mb-1 text-gray-600 font-bold">Panel Password</label>
                <input
                  type="password"
                  required
                  value={newRest.password}
                  onChange={(e) => setNewRest({ ...newRest, password: e.target.value })}
                  placeholder="Secret password"
                  className="w-full px-3 py-2 border rounded-xl"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block mb-1 text-gray-600 font-bold">Order Type</label>
                  <select
                    value={newRest.orderType}
                    onChange={(e) => setNewRest({ ...newRest, orderType: e.target.value })}
                    className="w-full px-2 py-2 border rounded-xl bg-white"
                  >
                    <option value="both">Both (Normal & Pre-Order)</option>
                    <option value="normal">Normal Only</option>
                    <option value="preorder">Pre-Order Only</option>
                  </select>
                </div>
                <div>
                  <label className="block mb-1 text-gray-600 font-bold">Priority Order</label>
                  <input
                    type="number"
                    value={newRest.priority}
                    onChange={(e) => setNewRest({ ...newRest, priority: e.target.value })}
                    className="w-full px-3 py-2 border rounded-xl"
                  />
                </div>
              </div>

              <button
                type="submit"
                className="w-full py-2.5 bg-emerald-600 text-white rounded-xl font-bold hover:bg-emerald-700 mt-2 text-sm shadow-md shadow-emerald-600/20"
              >
                Save Restaurant
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
